1	//! Handler for the `GET /agents/{name}/runs/{id}/events` WebSocket endpoint.
2	//!
3	//! Implements the **404-before-upgrade** pattern: the agent name and run id are
4	//! validated against the registry *before* the HTTP connection is promoted to a
5	//! WebSocket. A missing or name-mismatched run returns a plain HTTP 404 without
6	//! initiating an upgrade handshake.
7	//!
8	//! Once the handshake succeeds, [`handle_socket`] replays all previously
9	//! recorded events from sequence 0 and then delivers live events in real time.
10	//! The stream closes naturally once the first terminal event is delivered.
11	//! Client disconnects are observed via the inbound half of the socket; they do
12	//! **not** cancel the underlying run.
13	
14	use std::sync::Arc;
15	
16	use axum::{
17	    extract::{
18	        ws::{Message, WebSocket, WebSocketUpgrade},
19	        Path, State,
20	    },
21	    response::Response,
22	};
23	use futures_util::StreamExt;
24	use uuid::Uuid;
25	
26	use crate::{error::ServerError, registry::RunHandle, server::AppState};
27	
28	/// `GET /agents/{name}/runs/{id}/events` — subscribe to run events via WebSocket.
29	///
30	/// Performs a 404 check *before* accepting the WebSocket upgrade:
31	///
32	/// - If `id` is not a valid UUID, returns `400 Bad Request`.
33	/// - If no run with `id` exists in the registry, or the run's agent name does
34	///   not match `name`, returns `404 Not Found`.
35	/// - Otherwise returns `101 Switching Protocols` and streams all events for the
36	///   run, starting from sequence 0, as JSON text frames.
37	///
38	/// The stream closes after the terminal event (`RunCompleted` / `RunFailed`) is
39	/// delivered. Client disconnects are observed and handled gracefully; they do
40	/// **not** cancel the underlying run (WS subscribers are read-only observers).
41	///
42	/// # Errors
43	///
44	/// - [`ServerError::BadRequest`] (400) — `id` is not a valid UUID.
45	/// - [`ServerError::UnknownAgent`] (404) — the run does not exist or is owned
46	///   by a different agent.
47	pub(crate) async fn events<Ctx: Send + Sync + 'static>(
48	    State(state): State<AppState<Ctx>>,
49	    Path((name, id)): Path<(String, String)>,
50	    ws: WebSocketUpgrade,
51	) -> Result<Response, ServerError> {
52	    // Parse the run id; a non-UUID string is a client error (400).
53	    let run_id = Uuid::parse_str(&id)
54	        .map_err(|_| ServerError::BadRequest(format!("invalid run id: {id}")))?;
55	
56	    // Look up the run; absence or agent-name mismatch returns 404 without
57	    // upgrading the connection.
58	    let handle = state
59	        .registry
60	        .get(run_id)
61	        .filter(|h| h.agent_name == name)
62	        .ok_or_else(|| ServerError::UnknownAgent(format!("{name}/{id}")))?;
63	
64	    // Run confirmed — accept the WebSocket upgrade.
65	    Ok(ws.on_upgrade(move |socket| handle_socket(socket, handle)))
66	}
67	
68	/// Drive the WebSocket connection for a single run subscription.
69	///
70	/// Subscribes to the run's [`EventLog`](crate::event_log::EventLog) from
71	/// sequence 0, replaying any already-recorded events before switching to live
72	/// delivery. The loop ends when:
73	///
74	/// - The event stream ends (terminal event reached and delivered), or
75	/// - The client closes the connection (`socket.recv()` returns `None` or an
76	///   error).
77	///
78	/// Both halves of the socket are polled concurrently so that a client
79	/// disconnect is detected promptly even while events are still being replayed.
80	/// Disconnect does **not** cancel the run.
81	async fn handle_socket(mut socket: WebSocket, handle: Arc<RunHandle>) {
82	    let mut sub = handle.log.subscribe(0);
83	
84	    loop {
85	        tokio::select! {
86	            // Next event from the log (replay + live tail).
87	            ev = sub.next() => {
88	                match ev {
89	                    Some(ev) => {
90	                        let text = match serde_json::to_string(&ev) {
91	                            Ok(t) => t,
92	                            Err(_) => break,
93	                        };
94	                        if socket.send(Message::text(text)).await.is_err() {
95	                            break;
96	                        }
97	                    }
98	                    // Log stream ended — terminal event was already delivered.
99	                    None => {
100	                        // Send a proper Close frame so the client knows the
101	                        // stream is complete.
102	                        let _ = socket.send(Message::Close(None)).await;
103	                        break;
104	                    }
105	                }
106	            }
107	            // Inbound frames from the client (drain to observe close/disconnect).
108	            msg = socket.recv() => {
109	                match msg {
110	                    // Client closed the connection or a network error occurred.
111	                    None | Some(Err(_)) => break,
112	                    // A graceful WebSocket close frame: stop sending immediately
113	                    // instead of waiting for the next send to fail.
114	                    Some(Ok(Message::Close(_))) => break,
115	                    // Ignore inbound data, ping, and pong frames.
116	                    Some(Ok(_)) => {}
117	                }
118	            }
119	        }
120	    }
121	    // Dropping the socket finalises the TCP-level close.
122	}
