1	//! Run registry: in-flight and recently-completed runs, with TTL and count-cap retention.
2	//!
3	//! [`RunRegistry`] stores every run that was started by the axum server. Completed runs are
4	//! retained until they age out (TTL) or until the retained-run count exceeds `max_runs`
5	//! (FIFO-by-completion eviction). Live (non-terminal) runs are **never** evicted.
6	
7	use crate::event_log::EventLog;
8	use std::{
9	    collections::{HashMap, VecDeque},
10	    sync::{Arc, Mutex, RwLock},
11	    time::{Duration, Instant},
12	};
13	use tokio::sync::OnceCell;
14	use tokio_util::sync::CancellationToken;
15	use uuid::Uuid;
16	
17	// ── RunHandle ─────────────────────────────────────────────────────────────────
18	
19	/// Everything the server needs to track a single run.
20	pub(crate) struct RunHandle {
21	    /// Name of the agent that owns this run.
22	    pub agent_name: String,
23	    /// Append-only, bounded event log for this run.
24	    pub log: Arc<EventLog>,
25	    /// Cancellation token — drop or call `.cancel()` to abort the run.
26	    pub cancel: CancellationToken,
27	    /// Populated on the start-error path when the agent failed to launch before emitting any events.
28	    pub start_error: Mutex<Option<String>>,
29	    /// Set once the run enters a terminal state (via [`RunRegistry::note_terminal`]).
30	    pub terminal_at: Mutex<Option<Instant>>,
31	}
32	
33	// ── RegistryInner ─────────────────────────────────────────────────────────────
34	
35	/// Mutable state inside [`RunRegistry`], protected by an [`RwLock`].
36	struct RegistryInner {
37	    /// All live and recently-completed runs, keyed by run id.
38	    runs: HashMap<Uuid, Arc<RunHandle>>,
39	    /// Insertion order of terminal runs (oldest → newest). Used for FIFO eviction.
40	    completion_order: VecDeque<Uuid>,
41	}
42	
43	// ── RunRegistry ───────────────────────────────────────────────────────────────
44	
45	/// Registry of in-flight and recently-completed runs with TTL and count-cap retention.
46	///
47	/// Always constructed behind an [`Arc`] (see [`RunRegistry::new`]).
48	pub(crate) struct RunRegistry {
49	    inner: RwLock<RegistryInner>,
50	    /// How long a completed run is retained after becoming terminal.
51	    ttl: Duration,
52	    /// Maximum number of *completed* runs to retain simultaneously.
53	    max_runs: usize,
54	    /// [`EventLog`] capacity for each newly-created run.
55	    max_events_per_run: usize,
56	    /// Guards [`RunRegistry::spawn_sweeper`] so at most one background task is spawned.
57	    sweeper_once: OnceCell<()>,
58	}
59	
60	impl RunRegistry {
61	    /// Create a new registry wrapped in an [`Arc`].
62	    ///
63	    /// * `ttl` – retention window after a run becomes terminal.
64	    /// * `max_runs` – cap on retained completed runs; oldest-completed runs are evicted first.
65	    /// * `max_events_per_run` – passed to each run's [`EventLog::new`].
66	    pub fn new(ttl: Duration, max_runs: usize, max_events_per_run: usize) -> Arc<Self> {
67	        Arc::new(Self {
68	            inner: RwLock::new(RegistryInner {
69	                runs: HashMap::new(),
70	                completion_order: VecDeque::new(),
71	            }),
72	            ttl,
73	            max_runs,
74	            max_events_per_run,
75	            sweeper_once: OnceCell::new(),
76	        })
77	    }
78	
79	    /// Mint a new run id, build its handle, insert it into the registry, and return both.
80	    ///
81	    /// The run starts as non-terminal. Call [`note_terminal`](RunRegistry::note_terminal) once
82	    /// the run ends.
83	    pub fn create(&self, agent_name: String, cancel: CancellationToken) -> (Uuid, Arc<RunHandle>) {
84	        let id = Uuid::new_v4();
85	        let handle = Arc::new(RunHandle {
86	            agent_name,
87	            log: Arc::new(EventLog::new(self.max_events_per_run)),
88	            cancel,
89	            start_error: Mutex::new(None),
90	            terminal_at: Mutex::new(None),
91	        });
92	        let mut inner = self.inner.write().expect("RunRegistry RwLock poisoned");
93	        inner.runs.insert(id, Arc::clone(&handle));
94	        (id, handle)
95	    }
96	
97	    /// Look up a run by id. Returns `None` if it has been evicted or never existed.
98	    pub fn get(&self, id: Uuid) -> Option<Arc<RunHandle>> {
99	        let inner = self.inner.read().expect("RunRegistry RwLock poisoned");
100	        inner.runs.get(&id).cloned()
101	    }
102	
103	    /// Stamp the run as terminal at `now` and record it in the completion queue.
104	    ///
105	    /// Idempotent: calling more than once for the same id is a no-op after the first call.
106	    /// `now` is passed explicitly so callers can inject a deterministic clock in tests.
107	    pub fn note_terminal(&self, id: Uuid, now: Instant) {
108	        // Stamp `terminal_at` and enqueue into `completion_order` in ONE critical
109	        // section so a concurrent `sweep` cannot observe a half-applied state
110	        // (stamped-but-not-enqueued, or vice versa). Lock order is `inner` →
111	        // `terminal_at`, matching `sweep`, so the two never deadlock.
112	        let mut inner = self.inner.write().expect("RunRegistry RwLock poisoned");
113	        let Some(handle) = inner.runs.get(&id).cloned() else {
114	            return;
115	        };
116	        let mut t = handle
117	            .terminal_at
118	            .lock()
119	            .expect("terminal_at mutex poisoned");
120	        if t.is_none() {
121	            *t = Some(now);
122	            inner.completion_order.push_back(id);
123	        }
124	    }
125	
126	    /// Evict stale runs in two passes.
127	    ///
128	    /// **Pass 1 – TTL:** remove every terminal run whose `terminal_at + ttl ≤ now`.
129	    ///
130	    /// **Pass 2 – count cap:** while the number of still-present *terminal* runs exceeds
131	    /// `max_runs`, pop the front of the completion queue and evict it (skipping ids that
132	    /// were already removed by pass 1 or a previous cap iteration).
133	    ///
134	    /// Live (non-terminal) runs are **never** evicted by either pass.
135	    ///
136	    /// `now` is passed explicitly so callers can inject a deterministic clock in tests.
137	    pub fn sweep(&self, now: Instant) {
138	        let mut inner = self.inner.write().expect("RunRegistry RwLock poisoned");
139	        let ttl = self.ttl;
140	
141	        // Pass 1: TTL eviction. Track evicted ids so we can also clean them from
142	        // `completion_order`, preventing unbounded deque growth across long uptimes.
143	        let mut evicted: std::collections::HashSet<Uuid> = std::collections::HashSet::new();
144	        inner.runs.retain(|id, handle| {
145	            let t = handle
146	                .terminal_at
147	                .lock()
148	                .expect("terminal_at mutex poisoned");
149	            match *t {
150	                // Keep if still within the TTL window or non-terminal.
151	                Some(terminal_at) if terminal_at + ttl <= now => {
152	                    evicted.insert(*id);
153	                    false
154	                }
155	                _ => true,
156	            }
157	        });
158	        // Remove TTL-evicted ids from the completion queue to prevent memory leaks.
159	        if !evicted.is_empty() {
160	            inner.completion_order.retain(|id| !evicted.contains(id));
161	        }
162	
163	        // Pass 2: count-cap eviction (FIFO by completion order).
164	        let mut terminal_count = inner
165	            .runs
166	            .values()
167	            .filter(|h| {
168	                h.terminal_at
169	                    .lock()
170	                    .expect("terminal_at mutex poisoned")
171	                    .is_some()
172	            })
173	            .count();
174	
175	        while terminal_count > self.max_runs {
176	            // Pop from the front; skip ids already evicted (by pass 1 or an earlier iteration).
177	            let candidate = loop {
178	                match inner.completion_order.pop_front() {
179	                    None => break None,
180	                    Some(id) if inner.runs.contains_key(&id) => break Some(id),
181	                    Some(_already_gone) => continue,
182	                }
183	            };
184	            match candidate {
185	                None => break, // Safety valve: no more candidates.
186	                Some(id) => {
187	                    inner.runs.remove(&id);
188	                    terminal_count -= 1;
189	                }
190	            }
191	        }
192	    }
193	
194	    /// Spawn a background task that calls [`sweep`](RunRegistry::sweep) every 30 seconds.
195	    ///
196	    /// At most one task is spawned per registry instance (guarded by a [`OnceCell`]).
197	    /// The task holds a [`Weak`] reference so it automatically exits when the registry is dropped
198	    /// (i.e., no [`Arc`] remainders outside the spawned task itself).
199	    pub fn spawn_sweeper(self: &Arc<Self>) {
200	        // `OnceCell::set` succeeds exactly once; subsequent calls return `Err` which we ignore.
201	        if self.sweeper_once.set(()).is_ok() {
202	            let weak = Arc::downgrade(self);
203	            tokio::spawn(async move {
204	                let mut interval = tokio::time::interval(Duration::from_secs(30));
205	                loop {
206	                    interval.tick().await;
207	                    match weak.upgrade() {
208	                        None => return, // Registry dropped; exit.
209	                        Some(reg) => reg.sweep(Instant::now()),
210	                    }
211	                }
212	            });
213	        }
214	    }
215	}
216	
217	// ── Test helpers ──────────────────────────────────────────────────────────────
218	
219	#[cfg(test)]
220	impl RunRegistry {
221	    /// Returns the current length of `completion_order` for leak-regression tests.
222	    fn completion_queue_len(&self) -> usize {
223	        self.inner.read().unwrap().completion_order.len()
224	    }
225	}
226	
227	// ── Tests ─────────────────────────────────────────────────────────────────────
228	
229	#[cfg(test)]
230	mod tests {
231	    use super::*;
232	
233	    /// A completed run must not be evicted before its TTL expires, and must be evicted
234	    /// once the clock has advanced past `terminal_at + ttl`.
235	    #[test]
236	    fn ttl_evicts_after_deadline() {
237	        let reg = RunRegistry::new(Duration::from_secs(60), 1024, 1024);
238	        let (id, _h) = reg.create("a".into(), CancellationToken::new());
239	        let t0 = Instant::now();
240	        reg.note_terminal(id, t0);
241	        reg.sweep(t0 + Duration::from_secs(59));
242	        assert!(reg.get(id).is_some());
243	        reg.sweep(t0 + Duration::from_secs(61));
244	        assert!(reg.get(id).is_none());
245	    }
246	
247	    /// When the number of completed runs exceeds `max_runs`, the oldest-completed run must be
248	    /// evicted first, regardless of which run finished last.
249	    #[test]
250	    fn count_cap_evicts_oldest_completed_first() {
251	        let reg = RunRegistry::new(Duration::from_secs(3600), 2, 1024);
252	        let t0 = Instant::now();
253	        let ids: Vec<_> = (0..3)
254	            .map(|i| {
255	                let (id, _) = reg.create("a".into(), CancellationToken::new());
256	                reg.note_terminal(id, t0 + Duration::from_secs(i));
257	                id
258	            })
259	            .collect();
260	        reg.sweep(t0 + Duration::from_secs(3));
261	        assert!(reg.get(ids[0]).is_none()); // oldest-completed evicted
262	        assert!(reg.get(ids[1]).is_some()); // middle run survives (exactly one evicted)
263	        assert!(reg.get(ids[2]).is_some());
264	    }
265	
266	    /// TTL eviction must also remove the evicted ids from `completion_order` so that the
267	    /// deque does not grow without bound across long server uptimes (regression for the
268	    /// completion-queue leak found in review).
269	    #[test]
270	    fn ttl_eviction_cleans_completion_queue() {
271	        let reg = RunRegistry::new(Duration::from_secs(60), 1024, 1024);
272	        let t0 = Instant::now();
273	
274	        // Create and terminate three runs.
275	        for _ in 0..3 {
276	            let (id, _h) = reg.create("a".into(), CancellationToken::new());
277	            reg.note_terminal(id, t0);
278	        }
279	        assert_eq!(reg.completion_queue_len(), 3);
280	
281	        // Sweep before TTL — nothing evicted, queue unchanged.
282	        reg.sweep(t0 + Duration::from_secs(59));
283	        assert_eq!(reg.completion_queue_len(), 3);
284	
285	        // Sweep past TTL — all three runs evicted and queue must be empty.
286	        reg.sweep(t0 + Duration::from_secs(61));
287	        assert_eq!(reg.completion_queue_len(), 0);
288	    }
289	}
