/// `saw_terminal` must stay false and the generic message is used.
pub struct PartialThenEndRunner;

#[async_trait]
impl<Ctx: Send + Sync + 'static> Runner<Ctx> for PartialThenEndRunner {
    async fn run(
        &self,
        _agent: &(dyn Agent<Ctx> + '_),
        _ctx: RunContext<Ctx>,
        _input: AgentInput,
        _config: RunConfig,
    ) -> Result<RunResult, RunError> {
