    async fn run_streamed(
        &self,
        _agent: &(dyn Agent<Ctx> + '_),
        _ctx: RunContext<Ctx>,
        _input: AgentInput,
        _config: RunConfig,
    ) -> Result<RunResultStreaming, RunError> {
        let stream = stream::iter(vec![AgentEvent::TokenDelta {
            text: "hi".to_owned(),
        }])
        .boxed();
        Ok(RunResultStreaming::new(stream))
